const FUNCTIES = {
    "status":                  { code: 0x01, extra: "none" },
    "stop":                    { code: 0x02, extra: "none" },
    "omhoog_stop":             { code: 0x03, extra: "tijd_en_prio" }, 
    "omlaag_stop":             { code: 0x04, extra: "tijd_en_prio" },
    "omhoog":                  { code: 0x05, extra: "tijd_en_prio" },
    "omlaag":                  { code: 0x06, extra: "tijd_en_prio" },
    "flip_omhoog":             { code: 0x07, extra: "tijd_en_prio" },
    "flip_omlaag":             { code: 0x08, extra: "tijd_en_prio" },
    "prio_lock":               { code: 0x09, extra: "prioriteit" },
    "prio_unlock":             { code: 0x0A, extra: "prioriteit" },
    "leren_aan":               { code: 0x0B, extra: "none" },
    "leren_uit":               { code: 0x0C, extra: "none" },
    "prio_setten":             { code: 0x0D, extra: "prioriteit" },
    "prio_loschen":            { code: 0x0E, extra: "prioriteit" },
    "sensor_heffen":           { code: 0x0F, extra: "none" },
    "sensor_heffen_flip":      { code: 0x10, extra: "none" },
    "sensor_senken":           { code: 0x11, extra: "none" },
    "sensor_senken_flip":      { code: 0x12, extra: "none" }
};

function phcCrc(data) {
    let crc = 0xFFFF;
    for (let b of data) {
        crc ^= b;
        for (let i = 0; i < 8; i++) {
            if (crc & 1) crc = (crc >> 1) ^ 0x8408;
            else crc >>= 1;
        }
    }
    return crc ^ 0xFFFF;
}

const functieKey = msg.functie ? String(msg.functie).toLowerCase().trim() : "";
const functieDef = FUNCTIES[functieKey];

if (!functieDef) {
    node.error(`Onbekende JRM-functie: "${functieKey}".`);
    return null;
}

const adres = parseInt(msg.adres, 16);
const kanaal = parseInt(msg.kanaal);

let payloadBytes = [(kanaal << 5) | functieDef.code];

if (functieDef.extra === "tijd_en_prio") {
    // JRM verwacht prioriteit 7 (net als ESPHome) om niet genegeerd te worden
    const prio = msg.prioriteit !== undefined ? parseInt(msg.prioriteit) : 7;
    payloadBytes.push(prio & 0xFF);

    // Tijd in 100ms eenheden. 
    // msg.tijd = 5 (seconden) -> wordt 50 (wat de module leest als 5000ms).
    let tijdSec = 0;
    if (msg.tijd !== undefined) {
        tijdSec = Math.round(parseFloat(msg.tijd) * 10);
    }

    payloadBytes.push(tijdSec & 0xFF);
    payloadBytes.push((tijdSec >> 8) & 0xFF);

} else if (functieDef.extra === "prioriteit") {
    const prio = msg.prioriteit !== undefined ? parseInt(msg.prioriteit) : 7;
    payloadBytes.push(prio & 0xFF);
}

const startheader = [0xFE, 0x00, 0x06, 0x00]; 
const toggleLen = 0x00 | payloadBytes.length;
const cmdNoCrc = [adres, toggleLen, ...payloadBytes];
const crc = phcCrc([...startheader, ...cmdNoCrc]);
const raw = [...startheader, ...cmdNoCrc, crc & 0xFF, (crc >> 8) & 0xFF];

function escape(data) {
