}
const finalFrame = [0xC0, ...escape(raw), 0xC1];

msg.payload = finalFrame.map(b => b.toString(16).padStart(2, "0").toUpperCase()).join(" ");
msg.frame = msg.payload;
return msg;

// 1. Haal de bestaande buffer op (of maak een lege aan)
let buffer = context.get('rx_buffer') || [];

// 2. Voeg de nieuwe inkomende bytes toe aan de buffer
let incoming = Array.isArray(msg.payload) ? msg.payload : Array.from(msg.payload);
buffer = buffer.concat(incoming);

// 3. Zoek naar geldige C0 ... C1 frames in de buffer
let framesFound = 0;

while (true) {
    let startIdx = buffer.indexOf(0xC0);
    if (startIdx === -1) {
        buffer = []; // Geen start gevonden, gooi buffer leeg
        break;
    }

    let endIdx = buffer.indexOf(0xC1, startIdx + 1);
    if (endIdx === -1) {
        break; // Nog geen eind gevonden, wacht op meer data
    }

    // We hebben een frame! Haal het eruit.
    let frame = buffer.slice(startIdx, endIdx + 1);

    // Verwijder dit frame (en alles ervoor) uit de buffer
    buffer = buffer.slice(endIdx + 1);

    // --- Verwerk het frame ---
    processFrame(frame, node);
    framesFound++;
}

// 4. Sla de resterende buffer op voor de volgende keer
context.set('rx_buffer', buffer);

// Stop de flow hier, want we hebben al node.send gebruikt
return null;


// --- Hulpfunctie om een frame te verwerken ---
function processFrame(arr, nodeInstance) {
    let inner = arr.slice(1, -1);

    // Unescape
    let unescaped = [];
    for (let i = 0; i < inner.length; i++) {
        if (inner[i] === 0x7D && i + 1 < inner.length) {
            if (inner[i+1] === 0xE0) { unescaped.push(0xC0); i++; continue; }
            if (inner[i+1] === 0xE1) { unescaped.push(0xC1); i++; continue; }
            if (inner[i+1] === 0x5D) { unescaped.push(0x7D); i++; continue; }
        }
        unescaped.push(inner[i]);
    }

    let hexStr = unescaped.map(b => b.toString(16).padStart(2, '0').toUpperCase()).join(' ');

    // Zoek AMD/JRM adres (0x40 - 0x5F)
    let startIdx = -1;
    for (let i = 0; i < unescaped.length - 4; i++) {
        if ((unescaped[i] & 0xE0) === 0x40) { startIdx = i; break; }
    }

    if (startIdx === -1) {
        nodeInstance.warn(`Frame zonder AMD adres: ${hexStr}`);
        return;
    }

    const addr = unescaped[startIdx];
    const dip = addr & 0x1F;
    const length = unescaped[startIdx + 1] & 0x7F;
    const payload = unescaped.slice(startIdx + 2, startIdx + 2 + length);
    const crcRx = unescaped[startIdx + 2 + length] | (unescaped[startIdx + 3 + length] << 8);

    // CRC berekenen
    const crcInput = unescaped.slice(startIdx, startIdx + 2 + length);
    let crcCalc = 0xFFFF;
    for (let b of crcInput) {
        crcCalc ^= b;
        for (let i = 0; i < 8; i++) {
            if (crcCalc & 1) crcCalc = (crcCalc >> 1) ^ 0x8408;
            else crcCalc >>= 1;
        }
    }
    crcCalc ^= 0xFFFF;

    const ackOk = crcRx === crcCalc ? "OK" : "BAD";

    let statusByte = 0;
    let type = "onbekend";
    if (payload.length >= 2 && payload[0] === 0x00) { type = "ack"; statusByte = payload[1]; }
    else if (payload.length >= 2 && payload[0] === 0x01) { type = "status"; statusByte = payload[1]; }

    // Status omdraaien (kanaal 0 rechts)
    const statusStr = statusByte.toString(2).padStart(8, '0').split('').reverse().join('');
    const kanalenAan = [];
    for (let ch = 0; ch < 8; ch++) { if (statusByte & (1 << ch)) kanalenAan.push(ch); }

    const kanalenStr = kanalenAan.length > 0 ? kanalenAan.join(',') : '-';
    const crcInfo = `CRC rx=0x${crcRx.toString(16).toUpperCase()} calc=0x${crcCalc.toString(16).toUpperCase()}`;

    let outputText = "";
    if (type === "ack" || type === "status") {
        outputText = `${type} ${ackOk} : mod ${dip.toString().padStart(2, '0')} : status ${statusStr} (aan: ${kanalenStr})  [${crcInfo}]`;
    } else {
        outputText = `onbekend : mod ${dip.toString().padStart(2, '0')} : payload ${payload.map(b=>b.toString(16).padStart(2,'0')).join(' ')}  [${crcInfo}]`;
    }

    nodeInstance.send({ payload: outputText });
}

