// TEST FUNCTIE VOOR OUTPUT-STATUS (FE 00 06 00)
// Input:  msg.adres (bv. "02")
// Output: C0 FE 00 06 00 02 01 01 XX XX C1
// =====================================================================

function phcCrc(data) {
    let crc = 0xFFFF;
    for (let b of data) {
        crc ^= b;
        for (let i = 0; i < 8; i++) {
            if (crc & 1) crc = (crc >> 1) ^ 0x8408;
            else crc >>= 1;
        }
    }
    return crc ^ 0xFFFF;
}

// Adres ophalen
const adres = parseInt(msg.adres, 16);
if (isNaN(adres)) {
    node.error(`Ongeldig adres: "${msg.adres}"`);
    return null;
}

// De payload voor status-vraag is altijd 01
const payloadBytes = [0x01];

// Startheader voor outputs: FE 00 06 00
const startheader = [0xFE, 0x00, 0x06, 0x00]; 
const toggleLen = 0x00 | payloadBytes.length;
const cmdNoCrc = [adres, toggleLen, ...payloadBytes];
const crc = phcCrc([...startheader, ...cmdNoCrc]);
const raw = [...startheader, ...cmdNoCrc, crc & 0xFF, (crc >> 8) & 0xFF];

function escape(data) {
    const out = [];
    for (let b of data) {
        if (b === 0xC0) out.push(0x7D, 0xE0);
        else if (b === 0xC1) out.push(0x7D, 0xE1);
        else if (b === 0x7D) out.push(0x7D, 0x5D);
        else out.push(b);
    }
    return out;
}
const finalFrame = [0xC0, ...escape(raw), 0xC1];

msg.payload = finalFrame.map(b => b.toString(16).padStart(2, "0").toUpperCase()).join(" ");
msg.frame = msg.payload;
return msg;

const hex = String(msg.payload).replace(/\s/g, "");
msg.payload = Buffer.from(hex, "hex");
return msg;

// Input: msg.payload = [64,1,1,235,200,64,2,1,0,9,70] (array of Buffer)
// Output: losse pakketten met status

function phcCrc(data) {
    let crc = 0xFFFF;
    for (let b of data) {
        crc ^= b;
        for (let i = 0; i < 8; i++) {
            if (crc & 1) crc = (crc >> 1) ^ 0x8408;
            else crc >>= 1;
        }
    }
    return crc ^ 0xFFFF;
}

let buffer = context.get('bus_buffer') || [];
let incoming = Array.isArray(msg.payload) ? msg.payload : Array.from(msg.payload);
buffer = buffer.concat(incoming);

let framesFound = 0;

// We zoeken naar pakketten. Een pakket is minimaal 4 bytes (addr, len, crc_lo, crc_hi)
while (buffer.length >= 4) {
    const length = buffer[1] & 0x7F; // Lengte van de payload (zonder adres, lengte en crc)
    const totalLength = 2 + length + 2; // addr + len + payload + crc_lo + crc_hi

    // Als we nog niet genoeg bytes hebben voor dit pakket, wacht op meer data
    if (buffer.length < totalLength) {
        break;
    }

    // We hebben genoeg bytes, pak het frame
    let frame = buffer.slice(0, totalLength);
    let testCrc = frame[totalLength - 2] | (frame[totalLength - 1] << 8);
    let payloadWithoutCrc = frame.slice(0, totalLength - 2);

    if (phcCrc(payloadWithoutCrc) === testCrc) {
        // Geldig pakket!
        buffer = buffer.slice(totalLength); // Verwijder uit buffer
        processBusFrame(frame, node);
        framesFound++;
    } else {
        // Ongeldige CRC. Dit betekent dat we midden in een pakket zitten of ruis hebben.
        // Schuif 1 byte op en probeer opnieuw.
        buffer = buffer.slice(1);
    }
}

// Sla de resterende buffer op (bijv. als er nog een half pakket binnen is)
context.set('bus_buffer', buffer);
return null;

// --- Hulpfunctie om het gevonden pakket te analyseren ---
function processBusFrame(arr, nodeInstance) {
    const addr = arr[0];
    const dip = addr & 0x1F;
    const length = arr[1] & 0x7F;
    const payload = arr.slice(2, 2 + length);
    const crcRx = arr[2 + length] | (arr[3 + length] << 8);

    const hexStr = arr.map(b => b.toString(16).padStart(2, '0').toUpperCase()).join(' ');
    const crcInfo = `CRC 0x${crcRx.toString(16).toUpperCase().padStart(4,'0')}`;

    // Bepaal type
    let statusByte = 0;
    let type = "onbekend";

    if (payload.length >= 2 && payload[0] === 0x00) {
        type = "ack";
        statusByte = payload[1];
    } else if (payload.length >= 2 && payload[0] === 0x01) {
        type = "status";
        statusByte = payload[1];
    } else if (payload.length === 1) {
        type = "cmd";
        statusByte = payload[0];
    }

    // Status bits omdraaien (kanaal 0 = rechts)
    const statusStr = statusByte.toString(2).padStart(8, '0').split('').reverse().join('');
    const kanalenAan = [];
    for (let ch = 0; ch < 8; ch++) {
        if (statusByte & (1 << ch)) kanalenAan.push(ch);
    }
    const kanalenStr = kanalenAan.length > 0 ? kanalenAan.join(',') : '-';

    let output = "";
    if (type === "ack" || type === "status") {
        output = `bus = mod ${dip.toString().padStart(2,'0')} : status ${statusStr} (aan: ${kanalenStr})  [${crcInfo}]  -> ${hexStr}`;
    } else {
        output = `bus = mod ${dip.toString().padStart(2,'0')} : cmd/raw ${payload.map(b=>b.toString(16).padStart(2,'0')).join(' ')}  [${crcInfo}]  -> ${hexStr}`;
    }

    nodeInstance.send({ payload: output });
}

// =====================================================================
// RS485 MASTER PARSER (Buffered + JRM + Relais)
// =====================================================================

function calcCRC(integerArray) {
    let tempcrc = 65535;
    for (let i = 0; i < integerArray.length; i++) {
        let yy = integerArray[i];
        tempcrc = tempcrc ^ yy;
        for (let r = 0; r < 8; r++) {
            let som = tempcrc & 1;
            if (som == 1) {
                tempcrc = tempcrc >> 1;
                tempcrc = tempcrc ^ 33800;
            } else {
                tempcrc = (tempcrc / 2);
            }
        }
    }
    tempcrc = tempcrc ^ 65535;
    return tempcrc; // Geeft een 16-bit integer terug
}

// 1. Buffer ophalen en nieuwe data toevoegen
let buffer = context.get('rs485_buffer') || [];
let incoming = Array.isArray(msg.payload) ? msg.payload : Array.from(msg.payload);
buffer = buffer.concat(incoming);

let framesFound = [];

// 2. Zoek naar geldige frames in de buffer
while (buffer.length >= 5) {
    let foundValidFrame = false;

    // Probeer alle mogelijke lengtes tot de CRC klopt
    for (let i = 1; i <= buffer.length - 2; i++) {
        let testPayload = buffer.slice(0, i);
        let testCrcLo = buffer[i];
        let testCrcHi = buffer[i+1];

        let crcCalc = calcCRC(testPayload);
        let testCrc = testCrcLo | (testCrcHi << 8);

        if (crcCalc === testCrc) {
            // Geldig frame gevonden!
            let frame = buffer.slice(0, i + 2);
            framesFound.push(frame);

            // Verwijder dit frame uit de buffer
            buffer = buffer.slice(i + 2);
            foundValidFrame = true;
            break; 
        }
    }

    // Als er geen geldig frame is, wacht op meer data of schuif 1 byte op
    if (!foundValidFrame) {
        if (buffer.length > 64) { 
            buffer = buffer.slice(1); // Verwijder rommel
        } else {
            break; // Wacht op meer data
        }
    }
}

// Sla de resterende buffer op
context.set('rs485_buffer', buffer);

// 3. Analyseer de gevonden frames
if (framesFound.length > 0) {
    for (let frame of framesFound) {
        let hexString = frame.map(b => b.toString(16).padStart(2, '0').toUpperCase()).join(' ');
        let element = hexString.split(" ");

        let addr = parseInt(element[0], 16);
        let dip = addr & 0x1F;
        let length = parseInt(element[1], 16) & 0x7F;
        let payloadStr = element.slice(2, 2 + length);

        // --- JRM (Rolluik) Check ---
// --- JRM (Rolluik) Feedback Check ---
let p0 = parseInt(payloadStr[0], 16);
let functieCode = p0 & 0x1F;

if (length === 2 && (functieCode >= 0x03 && functieCode <= 0x08)) {
    let kanaal = (p0 >> 5) & 0x03;
    let actie = "";

    // De feedback codes uit de PDF
    if (functieCode === 0x03) actie = "start met DALEN (omlaag)";
    if (functieCode === 0x04) actie = "KLAAR met OMHOOG (gestopt)";
    if (functieCode === 0x05) actie = "KLAAR met OMLAAG (gestopt)";
    if (functieCode === 0x06) actie = "Timer gestart";
    if (functieCode === 0x07) actie = "Timer geannuleerd";
    if (functieCode === 0x08) actie = "Timer afgelopen (gestopt)";

    node.send({ payload: `bus = mod ${dip.toString().padStart(2,'0')} : JRM kanaal ${kanaal} -> ${actie} -> ${hexString}` });
}
        // --- Relais / Standaard Check ---
        else {
            let type = "cmd/raw";
            let statusByte = 0;

            if (payloadStr.length >= 2 && payloadStr[0] === "00") {
                type = "ack";
                statusByte = parseInt(payloadStr[1], 16);
            } else if (payloadStr.length >= 2 && payloadStr[0] === "01") {
                type = "status";
                statusByte = parseInt(payloadStr[1], 16);
            } else if (payloadStr.length === 1) {
                type = "cmd";
                statusByte = parseInt(payloadStr[0], 16);
            }

            if (type === "ack" || type === "status") {
                let statusStr = statusByte.toString(2).padStart(8, '0').split('').reverse().join('');
                let kanalenAan = [];
                for (let ch = 0; ch < 8; ch++) {
                    if (statusByte & (1 << ch)) kanalenAan.push(ch);
                }
                let kanalenStr = kanalenAan.length > 0 ? kanalenAan.join(',') : '-';
                node.send({ payload: `bus = mod ${dip.toString().padStart(2,'0')} : status ${statusStr} (aan: ${kanalenStr})  -> ${hexString}` });
            } else {
                node.send({ payload: `bus = mod ${dip.toString().padStart(2,'0')} : ${type} ${payloadStr.join(' ')}  -> ${hexString}` });
            }
        }
    }
}

return null;

