function calcCRC(integerArray) {
    let tempcrc = 65535;
    for (let i = 0; i < integerArray.length; i++) {
        let yy = integerArray[i];
        tempcrc = tempcrc ^ yy;
        for (let r = 0; r < 8; r++) {
            let som = tempcrc & 1;
            if (som == 1) {
                tempcrc = tempcrc >> 1;
                tempcrc = tempcrc ^ 33800;
            } else {
                tempcrc = (tempcrc / 2);
            }
        }
    }
    tempcrc = tempcrc ^ 65535;
    return tempcrc;
}

let buffer = context.get('rs485_buffer') || [];
let incoming = Array.isArray(msg.payload) ? msg.payload : Array.from(msg.payload);
buffer = buffer.concat(incoming);

let framesFound = [];

// CRC-geleide frame detectie
while (buffer.length >= 4) {
    let foundValidFrame = false;
    for (let i = 1; i <= buffer.length - 2; i++) {
        let testPayload = buffer.slice(0, i);
        let testCrcLo = buffer[i];
        let testCrcHi = buffer[i+1];

        let crcCalc = calcCRC(testPayload);
        let testCrc = testCrcLo | (testCrcHi << 8);

        if (crcCalc === testCrc) {
            let frame = buffer.slice(0, i + 2);
            framesFound.push(frame);
            buffer = buffer.slice(i + 2);
            foundValidFrame = true;
            break; 
        }
    }

    if (!foundValidFrame) {
        if (buffer.length > 64) { 
            buffer = buffer.slice(1);
        } else {
            break;
        }
    }
}

context.set('rs485_buffer', buffer);

if (framesFound.length > 0) {
    for (let frame of framesFound) {
        let hexString = frame.map(b => b.toString(16).padStart(2, '0').toUpperCase()).join(' ');
        let element = hexString.split(" ");

        let addr = parseInt(element[0], 16);

        // Filter STM-headers (FE) en broadcast adres (E0) eruit
        if (addr === 0xFE || addr === 0xE0) continue;

        // Formatteer het adres als 2-cijferige hex string (bijv. 41 ipv 65)
        let addrHex = addr.toString(16).toUpperCase().padStart(2, '0');

        // We negeren de lengte-byte van de module en kijken naar de daadwerkelijke payload.
        let payloadStr = element.slice(2, -2); 
        let length = payloadStr.length;

        // =================================================================
        // 1. IMD (INPUT MODULE) - Adressen 00 t/m 1F
        // =================================================================
        if (addr <= 0x1F) {
            if (length === 1) {
                let p0 = parseInt(payloadStr[0], 16);
                let kanaal = (p0 >> 4) & 0x0F; 
                let functieCode = p0 & 0x0F;

                let functieNaam = "";
                if (functieCode === 0x02) functieNaam = "Ein>0:Kort ingedrukt";
                if (functieCode === 0x03) functieNaam = "Aus<0:Losgelaten <1s";
                if (functieCode === 0x04) functieNaam = "Ein>1:Lang ingedrukt >1s";
                if (functieCode === 0x05) functieNaam = "Aus>1:Losgelaten >1s";
                if (functieCode === 0x06) functieNaam = "Ein>2:Extra lang ingedrukt >2s";
                if (functieCode === 0x07) functieNaam = "Aus:Losgelaten";

                if (payloadStr[0] === "00") {
                    node.send({ payload: `imd ${addrHex} : ack  : ${hexString} -> ik heb je indruk gezien` });
                } else {
                    node.send({ payload: `imd ${addrHex} : event: ${hexString} -> knop${kanaal}functie${functieCode} : ("${functieNaam}")` });
                }
            } 
            else if ((length === 4 || length === 5) && payloadStr[0] === "01") {
                let ledsLow = parseInt(payloadStr[1], 16); 
                let inLow   = parseInt(payloadStr[2], 16); 
                let inHigh  = parseInt(payloadStr[3], 16); 
                let ledsHigh = (length === 5) ? parseInt(payloadStr[4], 16) : 0;

                let knoppenAan = [];
                for (let ch = 0; ch < 8; ch++) {
                    if (inLow & (1 << ch)) knoppenAan.push(ch);
                    if (inHigh & (1 << ch)) knoppenAan.push(ch + 8);
                }

                let ledsAan = [];
                for (let ch = 0; ch < 8; ch++) {
                    if (ledsLow & (1 << ch)) ledsAan.push(ch);
                    if (ledsHigh & (1 << ch)) ledsAan.push(ch + 8);
                }

                let kStr = knoppenAan.length > 0 ? knoppenAan.join(',') : 'geen';
                let lStr = ledsAan.length > 0 ? ledsAan.join(',') : 'geen';
                let moduleType = (length === 5) ? "16-LEDs" : "8-LEDs";

                node.send({ payload: `imd ${addrHex} : status: ${hexString} -> Knoppen AAN [${kStr}] | LEDs AAN [${lStr}] (${moduleType})` });
            }
        }

        // =================================================================
        // 2. AMD / JRM (OUTPUT MODULES) - Adressen 40 t/m 5F
        // =================================================================
        else if (addr >= 0x40) {
            let p0 = parseInt(payloadStr[0], 16);
            let functieCode = p0 & 0x1F;
            let kanaal = (p0 >> 5) & 0x07;

            // JRM (Rolluik) Feedback Check
            if (length === 2 && (functieCode >= 0x03 && functieCode <= 0x08)) {
                let jch = (p0 >> 5) & 0x03;
                let actie = "";
                if (functieCode === 0x03) actie = "start met DALEN (omlaag)";
                if (functieCode === 0x04) actie = "KLAAR met OMHOOG (gestopt)";
                if (functieCode === 0x05) actie = "KLAAR met OMLAAG (gestopt)";
                if (functieCode === 0x06) actie = "Timer gestart";
                if (functieCode === 0x07) actie = "Timer geannuleerd";
                if (functieCode === 0x08) actie = "Timer afgelopen (gestopt)";

                node.send({ payload: `jrm ${addrHex} : event: ${hexString} -> kanaal ${jch} -> ${actie}` });
            } 
            // AMD (Relais) Status / ACK
            else if (length >= 2 && (payloadStr[0] === "00" || payloadStr[0] === "01")) {
                let type = payloadStr[0] === "00" ? "ack  " : "status";
                let stat = parseInt(payloadStr[1], 16);

                let statBin = stat.toString(2).padStart(8, '0').split('').reverse().join('');
                let kanalenAan = [];
                for (let ch = 0; ch < 8; ch++) {
                    if (stat & (1 << ch)) kanalenAan.push(ch);
                }
                let kStr = kanalenAan.length > 0 ? kanalenAan.join(',') : '-';

                node.send({ payload: `amd ${addrHex} : ${type}: ${hexString} -> ${statBin} (aan: ${kStr})` });
            }
            // AMD / JRM Commands (Lengte 1)
            else if (length === 1) {
                let desc = "";
                if (functieCode === 0x01) desc = `mod ${addrHex} wat is u status?`;
                else if (functieCode === 0x02) desc = `relais ${kanaal} AAN`;
                else if (functieCode === 0x03) desc = `relais ${kanaal} UIT`;
                else if (functieCode === 0x06) desc = `omschakelen relais ${kanaal}`;
                else desc = `functie ${functieCode} op kanaal ${kanaal}`;

                node.send({ payload: `amd ${addrHex} : cmd  : ${hexString} -> ${payloadStr[0]} *${desc}*` });
            }
            // JRM Commands met tijd (Lengte 3 of 4)
            else {
                node.send({ payload: `jrm ${addrHex} : cmd/raw: ${hexString} -> ${payloadStr.join(' ')}` });
            }
        }
    }
}

return null;

