                }

                node.send({ payload: `jrm ${addrHex} : cmd  : ${hexString} -> *${desc}*, tijd: ${tijdSec}s` });
            }
        }
    }
}

return null;

// =====================================================================
// RS485 MASTER PARSER (Perfecte vertaling van AMD & JRM commando's)
// =====================================================================

function calcCRC(data) {
    let crc = 0xFFFF;
    for (let i = 0; i < data.length; i++) {
        crc ^= data[i];
        for (let j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ 0x8408;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc ^ 0xFFFF;
}

let buffer = context.get('rs485_buffer') || [];
let incoming = Array.isArray(msg.payload) ? msg.payload : Array.from(msg.payload);
buffer = buffer.concat(incoming);

let framesFound = [];

while (buffer.length >= 4) {
    let foundValidFrame = false;
    for (let i = 1; i <= buffer.length - 2; i++) {
        let testPayload = buffer.slice(0, i);
        let testCrcLo = buffer[i];
        let testCrcHi = buffer[i+1];

        let crcCalc = calcCRC(testPayload);
        let testCrc = testCrcLo | (testCrcHi << 8);

        if (crcCalc === testCrc) {
            let frame = buffer.slice(0, i + 2);
            framesFound.push(frame);
            buffer = buffer.slice(i + 2);
            foundValidFrame = true;
            break; 
        }
    }
    if (!foundValidFrame) {
        buffer = buffer.slice(1);
    }
}

context.set('rs485_buffer', buffer);

// Dedupliceer
let uniekeFrames = [];
let batchSeen = new Set();
for (let frame of framesFound) {
    let hexString = frame.map(b => b.toString(16).padStart(2, '0').toUpperCase()).join(' ');
    if (!batchSeen.has(hexString)) {
        batchSeen.add(hexString);
        uniekeFrames.push(frame);
    }
}

if (uniekeFrames.length > 0) {
    for (let frame of uniekeFrames) {
        let hexString = frame.map(b => b.toString(16).padStart(2, '0').toUpperCase()).join(' ');
        let element = hexString.split(" ");

        let addr = parseInt(element[0], 16);
        if (addr === 0xFE || addr === 0xE0) continue;

        let addrHex = addr.toString(16).toUpperCase().padStart(2, '0');
        let payloadStr = element.slice(2, -2); 
        let length = payloadStr.length;

        // =================================================================
        // 1. IMD (INPUT MODULE)
        // =================================================================
        if (addr <= 0x1F) {
            if (length === 1) {
                let p0 = parseInt(payloadStr[0], 16);
                if (p0 === 0x00) {
                    node.send({ payload: `imd ${addrHex} : ack  : ${hexString} -> ACK (ik heb je bericht ontvangen)` });
                } else if (p0 === 0x01) {
                    node.send({ payload: `imd ${addrHex} : ack  : ${hexString} -> ACK / Ping (status opvraag)` });
                } else {
                    let kanaal = (p0 >> 4) & 0x0F; 
                    let functieCode = p0 & 0x0F;
                    let functieNaam = "Onbekende functie";
                    if (functieCode === 0x02) functieNaam = "Ein>0: Kort ingedrukt";
                    if (functieCode === 0x03) functieNaam = "Aus<0: Losgelaten <1s";
                    if (functieCode === 0x04) functieNaam = "Ein>1: Lang ingedrukt >1s";
                    if (functieCode === 0x05) functieNaam = "Aus>1: Losgelaten >1s";
                    if (functieCode === 0x06) functieNaam = "Ein>2: Extra lang ingedrukt >2s";
                    if (functieCode === 0x07) functieNaam = "Aus: Losgelaten";
                    node.send({ payload: `imd ${addrHex} : event: ${hexString} -> knop ${kanaal} functie ${functieCode} : (${functieNaam})` });
                }
            } 
            else if ((length === 4 || length === 5) && payloadStr[0] === "01") {
                let ledsLow = parseInt(payloadStr[1], 16); 
                let inLow   = parseInt(payloadStr[2], 16); 
                let inHigh  = parseInt(payloadStr[3], 16); 
                let ledsHigh = (length === 5) ? parseInt(payloadStr[4], 16) : 0;
                let knoppenAan = []; let ledsAan = [];
                for (let ch = 0; ch < 8; ch++) {
                    if (inLow & (1 << ch)) knoppenAan.push(ch);
                    if (inHigh & (1 << ch)) knoppenAan.push(ch + 8);
                    if (ledsLow & (1 << ch)) ledsAan.push(ch);
                    if (ledsHigh & (1 << ch)) ledsAan.push(ch + 8);
                }
                let kStr = knoppenAan.length > 0 ? knoppenAan.join(',') : 'geen';
                let lStr = ledsAan.length > 0 ? ledsAan.join(',') : 'geen';
                let moduleType = (length === 5) ? "16-LEDs" : "8-LEDs";
                node.send({ payload: `imd ${addrHex} : status: ${hexString} -> Knoppen AAN [${kStr}] | LEDs AAN [${lStr}] (${moduleType})` });
            }
        }

        // =================================================================
        // 2. AMD / JRM (OUTPUT MODULES)
        // =================================================================
        else if (addr >= 0x40) {
            let p0 = parseInt(payloadStr[0], 16);
            let functieCode = p0 & 0x1F;
            let kanaal = (p0 >> 5) & 0x07;

            // JRM (Rolluik) feedback events (van module naar controller)
            if (length === 2 && (functieCode >= 0x03 && functieCode <= 0x08)) {
                let jch = (p0 >> 5) & 0x03;
                let actie = "Onbekend";
                if (functieCode === 0x03) actie = "start met DALEN (omlaag)";
                if (functieCode === 0x04) actie = "KLAAR met OMHOOG (gestopt)";
                if (functieCode === 0x05) actie = "KLAAR met OMLAAG (gestopt)";
                if (functieCode === 0x06) actie = "Timer gestart";
                if (functieCode === 0x07) actie = "Timer geannuleerd";
                if (functieCode === 0x08) actie = "Timer afgelopen (gestopt)";
                node.send({ payload: `jrm ${addrHex} : event: ${hexString} -> kanaal ${jch} -> ${actie}` });
            } 
            // AMD/JRM Status / ACK
            else if (length >= 2 && (payloadStr[0] === "00" || payloadStr[0] === "01")) {
                let type = payloadStr[0] === "00" ? "ack  " : "status";
                let stat = parseInt(payloadStr[1], 16);
                let statBin = stat.toString(2).padStart(8, '0').split('').reverse().join('');
                let kanalenAan = [];
                for (let ch = 0; ch < 8; ch++) {
                    if (stat & (1 << ch)) kanalenAan.push(ch);
                }
                let kStr = kanalenAan.length > 0 ? kanalenAan.join(',') : '-';
                node.send({ payload: `amd ${addrHex} : ${type}: ${hexString} -> ${statBin} (aan: ${kStr})` });
            }
            // Commands
            else {
                let desc = "";
                let tijdVal = 0;

                // Als de tijd erin zit (lengte 3 of 4), bereken de 16-bit waarde (little endian)
                if (length >= 3) {
                    tijdVal = parseInt(payloadStr[length-2], 16) | (parseInt(payloadStr[length-1], 16) << 8);
                }

                if (length === 1) {
                    // ---- 1-byte commando's ----
                    if (payloadStr[0] === "00") desc = "ACK (bevestiging)";
                    else if (payloadStr[0] === "01") desc = "Status opvragen";
                    else if (functieCode === 0x02) desc = `Relais ${kanaal} AAN / JRM Stop`;
                    else if (functieCode === 0x03) desc = `Relais ${kanaal} UIT`;
                    else if (functieCode === 0x04) desc = `Vergrendel AAN (kanaal ${kanaal})`;
                    else if (functieCode === 0x05) desc = `Vergrendel UIT (kanaal ${kanaal})`;
                    else if (functieCode === 0x06) desc = `Omschakelen (kanaal ${kanaal})`;
                    else if (functieCode === 0x07) desc = `Ontgrendel (kanaal ${kanaal})`;
                    else desc = `Onbekende functie 0x${functieCode.toString(16).toUpperCase()}`;

                    node.send({ payload: `amd ${addrHex} : cmd  : ${hexString} -> ${payloadStr[0]} *${desc}*` });
                } 
                else if (length === 2) {
                    // ---- 2-byte commando's (Meestal JRM Prioriteit) ----
                    if (functieCode === 0x09) desc = "Prio lock";
                    else if (functieCode === 0x0A) desc = "Prio unlock";
                    else if (functieCode === 0x0D) desc = "Prio setten";
                    else if (functieCode === 0x0E) desc = "Prio loschen";
                    else desc = `Commando 0x${functieCode.toString(16).toUpperCase()}`;

                    let prio = parseInt(payloadStr[1], 16);
                    node.send({ payload: `jrm ${addrHex} : cmd  : ${hexString} -> *${desc}*, kanaal ${kanaal}, prio: ${prio}` });
                } 
                else if (length === 3) {
                    // ---- 3-byte commando's (Meestal AMD Timer) ----
                    if (functieCode === 0x08) desc = "Aan vertraagd";
                    else if (functieCode === 0x09) desc = "Uit vertraagd";
                    else if (functieCode === 0x0A) desc = "Aan met timer";
                    else if (functieCode === 0x0B) desc = "Uit met timer";
                    else if (functieCode === 0x0C) desc = "Omschakelen vertraagd";
                    else if (functieCode === 0x0D) desc = "Omschakelen met timer";
                    else if (functieCode === 0x10) desc = "Timer Addieren";
                    else if (functieCode === 0x11) desc = "Timer Setten";
                    // JRM 3-byte varianten
                    else if (functieCode === 0x13) desc = "JRM Zeitmessung verz. an";
                    else if (functieCode === 0x14) desc = "JRM Zeitmessung verz. aus";
                    else if (functieCode === 0x15) desc = "JRM Zeitmessung Timer an";
                    else desc = `Commando 0x${functieCode.toString(16).toUpperCase()}`;

                    node.send({ payload: `amd ${addrHex} : cmd  : ${hexString} -> *${desc}*, kanaal ${kanaal}, tijd: ${tijdVal}` });
                } 
                else {
                    // ---- 4-byte commando's (JRM Rolluik met tijd) ----
                    if (functieCode === 0x03) desc = "Omschakelen heffen stop";
                    else if (functieCode === 0x04) desc = "Omschakelen dalen stop";
                    else if (functieCode === 0x05) desc = "Omhoog (heffen)";
                    else if (functieCode === 0x06) desc = "Omlaag (dalen)";
                    else if (functieCode === 0x07) desc = "Flip omhoog";
                    else if (functieCode === 0x08) desc = "Flip omlaag";
                    else desc = `Commando 0x${functieCode.toString(16).toUpperCase()}`;

                    let prio = parseInt(payloadStr[1], 16);
                    node.send({ payload: `jrm ${addrHex} : cmd  : ${hexString} -> *${desc}*, kanaal ${kanaal}, prio: ${prio}, tijd: ${tijdVal}` });
                }
            }
        }
    }
}

return null;

// =====================================================================
// BOUW IMD-FRAME (Input Module)
// =====================================================================

function phcCrc(data) {
    let crc = 0xFFFF;
    for (let b of data) {
        crc ^= b;
        for (let i = 0; i < 8; i++) {
            if (crc & 1) crc = (crc >> 1) ^ 0x8408;
            else crc >>= 1;
        }
    }
    return crc ^ 0xFFFF;
}

const adres = parseInt(msg.adres, 16);
if (isNaN(adres)) return null;

const kanaal = parseInt(msg.kanaal) || 0;
let functieCode = 0x01; 
let functieNaam = "Status opvragen";

let f = String(msg.functie).toLowerCase().trim();

// Mapping op basis van de namen en nummers
if       (f === "status"          || f === "1") { functieCode = 0x01; functieNaam = "Status"; }
else if (f === "aan > 0 seconden" || f === "2") { functieCode = 0x02; functieNaam = "Aan > 0 seconden"; }
else if (f === "uit < 1 seconden" || f === "3") { functieCode = 0x03; functieNaam = "Uit < 1 seconden"; }
else if (f === "aan > 1 seconden" || f === "4") { functieCode = 0x04; functieNaam = "Aan > 1 seconden"; }
else if (f === "uit > 1 seconden" || f === "5") { functieCode = 0x05; functieNaam = "Uit > 1 seconden"; }
else if (f === "aan > 2 seconden" || f === "6") { functieCode = 0x06; functieNaam = "Aan > 2 seconden"; }
else if (f === "losgelaten" || f === "7") { functieCode = 0x07; functieNaam = "Losgelaten"; }
else {
    node.error(`Onbekende IMD-functie: "${msg.functie}"`);
    return null;
}

let payloadByte = (functieCode === 0x01) ? 0x01 : ((kanaal << 4) | functieCode);

let finalFrameParts = [];

if (functieCode === 0x01) {
    // --- STATUS OPVRAGEN (Gebruikt de 06 header, mét lengte byte) ---
    let startheader = [0xFE, 0x00, 0x06, 0x00];
    let toggleLen = 0x01; // Lengte is 1
    let cmdNoCrc = [adres, toggleLen, payloadByte];
    let crc = phcCrc([...startheader, ...cmdNoCrc]);
    finalFrameParts = [...startheader, ...cmdNoCrc, crc & 0xFF, (crc >> 8) & 0xFF];
} else {
    // --- KNOP/INPUT COMMANDO (Gebruikt de 21 header, ZONDER extra 00 byte) ---
    let startheader = [0xFE, 0x00, 0x21, 0x00];
    let cmdNoCrc = [adres, payloadByte]; // Direct adres en payload
    let crc = phcCrc([...startheader, ...cmdNoCrc]);
    finalFrameParts = [...startheader, ...cmdNoCrc, crc & 0xFF, (crc >> 8) & 0xFF];
}

function escape(data) {
    const out = [];
    for (let b of data) {
        if (b === 0xC0) out.push(0x7D, 0xE0);
        else if (b === 0xC1) out.push(0x7D, 0xE1);
        else if (b === 0x7D) out.push(0x7D, 0x5D);
        else out.push(b);
    }
    return out;
}
const finalFrame = [0xC0, ...escape(finalFrameParts), 0xC1];

msg.payload = finalFrame.map(b => b.toString(16).padStart(2, "0").toUpperCase()).join(" ");
msg.frame = msg.payload;
msg.info = `IMD ${msg.adres}.${kanaal} -> ${functieNaam}`;
return msg;
